import{_ as a,a0 as r,w as i,s as p,ao as l,I as u,x as n,a1 as o,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Ubuntu 的开发者准备开发一个仅基于 Unity 8的新风格 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 的开发者准备开发一个仅基于 Unity 8的新风格 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 的开发者准备开发一个仅基于 Unity 8的新风格 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 的开发者准备开发一个仅基于 Unity 8的新风格 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Ubuntu Developers Propose a New Flavor Based Only on Unity 8","title":"Ubuntu 的开发者准备开发一个仅基于 Unity 8的新风格","tag":"201405","desc":""},"relativePath":"201405/Ubuntu Developers Propose a New Flavor Based Only on Unity 8.md","filePath":"[post].md"}'),U={name:"201405/Ubuntu Developers Propose a New Flavor Based Only on Unity 8.md"};function d(y,t,b,m,T,f){const e=r("Link");return i(),p("div",null,[t[11]||(t[11]=l('<h1 id="ubuntu-的开发者准备开发一个仅基于-unity-8的新风格" tabindex="-1">Ubuntu 的开发者准备开发一个仅基于 Unity 8的新风格 <a class="header-anchor" href="#ubuntu-的开发者准备开发一个仅基于-unity-8的新风格" aria-label="Permalink to “Ubuntu 的开发者准备开发一个仅基于 Unity 8的新风格”">​</a></h1><p><img src="http://i1-news.softpedia-static.com/images/news2/Ubuntu-Developers-Propose-a-New-Flavor-Based-Only-on-Unity-8-442262-2.jpg" alt="Current Unity 7 desktop in Ubuntu 14.04 LTS"></p><p><strong>Ubuntu 的开发者提出将开发一个单独使用 Unity 8的新风格，以帮助他们自由的实验而不必担心搞乱操作系统稳定。</strong></p><p>如果你的环境满足安装需要的话，现在可以在Ubuntu 14.04 LTS中安装体验下 Unity 8 桌面环境的预览版了。现在，新的桌面还不能在专有驱动下运行，因为它依赖于 Mir，而这玩意儿还没有获得 NVIDIA 和 AMD 的官方支持。</p><p>无论如何，有一个新的 Ubuntu 风格对于开发者在新的生态环境中测试他们的创意都会有巨大的帮助，而且从　USB Stick 里启动十分方便还能体验大多数的移植性应用。</p><p>“桌面环境开发组很希望为 Ubuntu 增加一个新的风格（嘘~，我们并不是计划现在就发行一个正式的版本），这个风格将包括为触屏项目开发的Unity 8桌面和新的应用。最初的意图是提供一个产品使得开发人员可以在做一个基于该软件的桌面产品的时候可以估算出所需要的的工作量，并建立一个可以由实验来找出所需的最佳结合方式的空间。”</p><p>“我们仍将计划融合当前的桌面环境，但是我们不希望给用户带来不安稳和造成不便，而且希望并行的发展这个新风格可以使我们真正实现在软件已经准备就绪的时候再迁移，而不是迁移后再解决用户的原有软件的兼容问题。” Ubuntu 的开发者 Iain Lane说。</p><p>Ubuntu 14.04 LTS 现在默认使用 Unity 7，而且可能这至少将持续到下一个版本 Ubuntu 14.10。Ubuntu 开发者的目标是最迟在下一个 LTS：Ubuntu 16.04 中让 Unity 8 和 Mir 成为默认的配置，但是如果事情进展的顺利，我们可能会在此之前就能成功。</p><p>这个新风格的名字是什么还不清楚，但是如果地位确定的话，我们可能在接下来的几个月就可以得到ISO文件。这将会使得用户更容易地测试 Unity 8 ，而且可以在它成为默认配置之前体验一把。</p><p>当 Canonical 用 Unity 替换旧的 GNOME 2 的时候，这个转换引起的震动是如此之大，以至于直到今天在论坛中还时不时的被人提及。有一个专门的 Unity 8 风格可能会缓解这个问题。</p><hr>',11)),u("p",null,[t[1]||(t[1]=n("via: ",-1)),o(e,{href:"http://news.softpedia.com/news/Ubuntu-Developers-Propose-a-New-Flavor-Based-Only-on-Unity-8-442262.shtml"},{default:s(()=>[...t[0]||(t[0]=[n("http://news.softpedia.com/news/Ubuntu-Developers-Propose-a-New-Flavor-Based-Only-on-Unity-8-442262.shtml",-1)])]),_:1})]),u("p",null,[t[4]||(t[4]=n("译者：",-1)),o(e,{href:"https://github.com/crowner"},{default:s(()=>[...t[2]||(t[2]=[n("crowner",-1)])]),_:1}),t[5]||(t[5]=n(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),u("p",null,[t[8]||(t[8]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[n("Linux中国",-1)])]),_:1}),t[10]||(t[10]=n(" 荣誉推出",-1))])])}const _=a(U,[["render",d]]);export{C as __pageData,_ as default};
